#!/usr/bin/env ruby
# frozen_string_literal: true
#
# imported_bindings_parity — compare the self-hosted imported-binding generator
# against the Ruby host generator and the checked-in modules.
#
# Three axes per binding:
#   A. self-generated bytes vs checked-in std/<name>.mt   (what `--check` reports)
#   B. self-generated bytes vs the Ruby host generator     (byte contract)
#   C. registry parity: host default_bindings vs the self registry
#
# The host has no `imported-bindings` CLI command (the self-only command is a
# documented deliberate difference), so the host side is generated in-process
# through MilkTea::ImportedBindings::Binding#generate.
#
# Usage:
#   tools/imported_bindings_parity.rb [options]
#
# Options:
#   --self PATH      self-host compiler binary (default: build/stage2/mtc)
#   --json PATH      write the machine-readable report
#   --soft           exit 0 when bindings differ but every diff is classified
#   -q, --quiet      print only the summary
#   -f, --filter RE  only bindings whose name matches RE
#   --max-diffs N    first-diff line windows to print per binding (default: 3)
#   -h, --help       show this message
#
# Exit status: 0 when the self matches the host everywhere; 1 otherwise.  With
# --soft, a classified difference does not fail; a *changed* binding that cannot
# be classified always fails.  A missing registry entry always fails.

require "json"
require "open3"
require "pathname"
require "time"

ROOT = File.expand_path("..", __dir__)
$LOAD_PATH.unshift(File.join(ROOT, "lib"))
require "milk_tea"
require "milk_tea/bindings"

self_bin = nil
json_path = nil
soft = false
quiet = false
filter = nil
max_diffs = 3

argv = ARGV.dup
until argv.empty?
  a = argv.shift
  case a
  when "--self"      then self_bin = argv.shift
  when "--json"      then json_path = argv.shift
  when "--soft"      then soft = true
  when "-q", "--quiet" then quiet = true
  when "-f", "--filter" then filter = argv.shift
  when "--max-diffs" then max_diffs = argv.shift.to_i
  when "-h", "--help"
    puts File.read(__FILE__).lines.drop(2).take_while { |l| l.start_with?("#") }
             .map { |l| l.sub(/\A# ?/, "") }.join
    exit 0
  else
    warn "unknown option: #{a}"
    exit 1
  end
end

self_bin ||= File.join(ROOT, "build", "stage2", "mtc")
self_bin = File.expand_path(self_bin)
unless File.executable?(self_bin)
  warn "error: self-host compiler not found or not executable: #{self_bin}"
  warn "       build one with: ruby -Ilib bin/mtc build projects/mtc -I . --no-cache -o #{self_bin}"
  exit 1
end

newest_src = Dir.glob(File.join(ROOT, "projects", "mtc", "src", "**", "*.mt")).map { |f| File.mtime(f) }.max
warn "warning: #{self_bin} is older than the newest self-host source — rebuild it for accurate parity." if newest_src && File.mtime(self_bin) < newest_src

HOST_BINDINGS = MilkTea::ImportedBindings.default_bindings(root: MilkTea.root)
HOST_NAMES = HOST_BINDINGS.map(&:name).freeze

def self_registry_names
  path = File.join(ROOT, "projects", "mtc", "src", "mtc", "imported_bindings", "registry.mt")
  File.read(path).scan(/^\s*name = "([^"]+)"/).flatten
end

def snake_case(name)
  name.to_s
      .gsub(/([A-Z]+)([A-Z][a-z])/, '\1_\2')
      .gsub(/([a-z0-9])([A-Z])/, '\1_\2')
      .downcase
      .gsub(/([a-z])(\d+)_d\b/, '\1_\2d')
end

def policy_for(binding)
  JSON.parse(File.read(binding.policy_path))
rescue StandardError
  {}
end

def policy_has_opengl?(policy)
  policy.dig("functions", "rename_rules").to_a.any? { |rule| rule["kind"] == "opengl" }
end

def first_diff(a, b)
  return nil if a.nil? || b.nil?

  limit = [a.bytesize, b.bytesize].min
  idx = 0
  idx += 1 while idx < limit && a.getbyte(idx) == b.getbyte(idx)
  line = a.byteslice(0, idx).count("\n") + 1
  { offset: idx, line: line }
end

def first_diff_line_index(a, b)
  return nil if a.nil? || b.nil?

  al = a.lines
  bl = b.lines
  i = 0
  i += 1 while i < [al.size, bl.size].min && al[i] == bl[i]
  i
end

TYPE_LINE = /\Apublic (type|opaque) ([A-Za-z0-9_]+)(.*)/

def policy_type_overrides(policy)
  policy.dig("types", "overrides").to_a.each_with_object({}) do |o, out|
    out[o["raw"]] = o["name"] if o["raw"]
  end
end

# Classify the first host-vs-self divergence.  The buckets are deliberately
# coarse: they name the emitter gap the implementer must close, not every byte.
def classify(host, self_src, policy)
  return "host-empty" if host.nil? || host.empty?
  return "self-empty" if self_src.nil? || self_src.empty?

  hlines = host.lines
  slines = self_src.lines

  # The self currently appends one method-source import per method spec; the
  # host deduplicates them.
  if slines.tally.any? { |line, count| count > 1 && line.start_with?("import ") }
    matches = slines.tally.select { |line, count| count > 1 && line.start_with?("import ") }.keys
    host_imports = hlines.select { |l| l.start_with?("import ") }
    return "duplicate-import" if matches.any? { |l| !host_imports.include?(l) || host_imports.count(l) < slines.count(l) }
  end

  i = first_diff_line_index(host, self_src)
  return "unknown" if i.nil?

  h = hlines[i].to_s.chomp
  s = slines[i].to_s.chomp

  hm = h.match(TYPE_LINE)
  sm = s.match(TYPE_LINE)
  if hm && sm
    hkind, hname, hrest = hm.captures
    skind, sname, srest = sm.captures
    overrides = policy_type_overrides(policy)
    return "missing-type-override" if overrides.any? { |raw, name| hrest.include?(raw) && hname == name }
    return "type-opaque-mismatch" if hkind != skind
    return "reserved-name" if hname == "#{sname}_" || sname == "#{hname}_"
    return "type-name-snake-cased" if snake_case(hname) == sname && hrest == srest
    return "missing-type-override" if hrest != srest
    return "acronym-boundary" if hname.delete("_").downcase == sname.delete("_").downcase
    return "type-name-other"
  end

  return "method-import" if h.start_with?("import ") || s.start_with?("import ")

  # Function signatures, foreign declarations, and method wrappers all carry a
  # function name; classify the name transformation first.
  if h.include?("function ") && s.include?("function ")
    hname = h[/function ([A-Za-z0-9_]+)/, 1]
    sname = s[/function ([A-Za-z0-9_]+)/, 1]
    if hname && sname && hname != sname
      return "opengl-name" if policy_has_opengl?(policy)
      return "digit-lower-underscore" if sname.match?(/\d_\w/) && !hname.match?(/\d_\w/)
      return "_d-fixup" if sname.match?(/\w_d\b/) && !hname.match?(/\w_d\b/)
      return "acronym-boundary" if hname.delete("_").downcase == sname.delete("_").downcase
      return "reserved-name" if sname == "#{hname}_" || hname == "#{sname}_"
      return "function-name-other"
    end
    diff_at = (0...[h.length, s.length].min).find { |j| h[j] != s[j] } || [h.length, s.length].min
    arrow = h.index("->")
    open_paren = h.index("(")
    close_paren = h.index(")")
    return "return-type-mapping" if arrow && diff_at >= arrow
    return "param-type-mapping" if open_paren && close_paren && diff_at > open_paren && diff_at <= close_paren
    return "signature-other"
  end

  if h.include?("const ") && s.include?("const ")
    hname = h[/const ([A-Za-z0-9_]+)/, 1]
    sname = s[/const ([A-Za-z0-9_]+)/, 1]
    if hname && sname && hname != sname
      return "reserved-name" if sname == "#{hname}_" || hname == "#{sname}_"
      return "constant-name"
    end
    return "const-type-mapping"
  end
  "unknown"
end

def bucket_json(bucket)
  { "bucket" => bucket }
end

results = []
registry_names = self_registry_names
missing_registry = HOST_NAMES - registry_names
extra_registry = registry_names - HOST_NAMES

HOST_BINDINGS.each do |binding|
  next if filter && !binding.name.match?(Regexp.new(filter))

  checked_in = File.file?(binding.binding_path) ? File.binread(binding.binding_path) : nil
  policy = policy_for(binding)

  host = nil
  host_error = nil
  begin
    host = binding.generate(module_roots: [MilkTea.root])
  rescue StandardError => e
    host_error = "#{e.class}: #{e.message}"
  end

  self_out, self_err, status = Open3.capture3(self_bin, "imported-bindings", binding.name, "--stdout", chdir: ROOT)
  self_src = status.success? ? self_out : nil
  self_error = status.success? ? nil : self_err.strip

  self_vs_checked = !checked_in.nil? && !self_src.nil? && self_src == checked_in
  host_vs_checked = !checked_in.nil? && !host.nil? && host == checked_in
  self_vs_host = !host.nil? && !self_src.nil? && self_src == host

  bucket =
    if missing_registry.include?(binding.name) then "missing-registry-entry"
    elsif host.nil? then "host-error"
    elsif self_src.nil? then "self-error"
    elsif self_vs_host then "verified"
    else classify(host, self_src, policy)
    end

  diff_index = first_diff_line_index(host, self_src)
  host_window = host && diff_index ? host.lines.slice(diff_index, max_diffs) : []
  self_window = self_src && diff_index ? self_src.lines.slice(diff_index, max_diffs) : []

  results << {
    "name" => binding.name,
    "path" => binding.binding_path,
    "host_bytes" => host&.bytesize,
    "self_bytes" => self_src&.bytesize,
    "checked_in_bytes" => checked_in&.bytesize,
    "host_vs_checked_in" => host_vs_checked,
    "self_vs_checked_in" => self_vs_checked,
    "self_vs_host" => self_vs_host,
    "bucket" => bucket,
    "host_error" => host_error,
    "self_error" => self_error,
    "first_diff_self_vs_host" => first_diff(self_src, host),
    "first_diff_self_vs_checked_in" => first_diff(self_src, checked_in),
    "host_lines" => host_window,
    "self_lines" => self_window
  }
end

counts = results.group_by { |r| r["bucket"] }.transform_values(&:size)
verified = counts.fetch("verified", 0)
changed = results.size - verified
unknown = results.select { |r| r["bucket"] == "unknown" }
error_rows = results.select { |r| %w[host-error self-error].include?(r["bucket"]) }

unless quiet
  results.each do |r|
    printf("%-22s %-24s host=%7s self=%7s checked=%7s %s\n",
           r["name"], r["bucket"], r["host_bytes"] || "-", r["self_bytes"] || "-",
           r["checked_in_bytes"] || "-", r["self_vs_host"] ? "ok" : "DIFF")
    next if r["self_vs_host"]

    if r["host_error"]
      puts "  host error: #{r["host_error"]}"
      next
    end
    if r["self_error"]
      puts "  self error: #{r["self_error"]}"
      next
    end
    r["host_lines"].to_a.zip(r["self_lines"].to_a).each do |h, s|
      puts "  H: #{h&.chomp}"
      puts "  S: #{s&.chomp}"
    end
  end
  puts
end

puts "bindings=#{results.size} verified=#{verified} changed=#{changed} " \
     "buckets=#{counts.sort.reject { |k, _| k == "verified" }.map { |k, v| "#{k}:#{v}" }.join(",")}"
puts "registry missing=#{missing_registry.inspect} extra=#{extra_registry.inspect}" unless missing_registry.empty? && extra_registry.empty?

report = {
  "generated_at" => Time.now.utc.iso8601,
  "self" => self_bin,
  "bindings" => results,
  "registry" => {
    "host" => HOST_NAMES,
    "self" => registry_names,
    "missing" => missing_registry,
    "extra" => extra_registry
  },
  "summary" => {
    "total" => results.size,
    "verified" => verified,
    "changed" => changed,
    "buckets" => counts
  }
}
File.write(json_path, JSON.pretty_generate(report) + "\n") if json_path

exit 1 unless unknown.empty?
exit 1 unless missing_registry.empty? && extra_registry.empty?
exit 1 unless error_rows.empty?
exit 0 if soft
exit 1 unless changed.zero?
exit 0
